"""id — virtues_c."""

T = {
"virtues_051": ("Apa yang Luqman nasihatkan kepada anaknya tentang suara?", ["Melunakkan suara: seburuk-buruk suara adalah suara keledai", "Berbicara sangat keras", "Tidak pernah berbicara", "Bernyanyi saat berjalan"], "«Dan sederhanakanlah dalam berjalan dan lunakkanlah suaramu: sesungguhnya seburuk-buruk suara ialah suara keledai»."),
"virtues_052": ("Tiga nasihat apa yang Luqman berikan kepada anaknya sebelum berbicara tentang kesabaran?", ["Menegakkan salat, menyuruh berbuat makruf, mencegah kemungkaran", "Bepergian, berdagang, menulis", "Sedikit makan, sedikit tidur, sedikit bicara", "Membangun, menanam, memanen"], "«Wahai anakku! Laksanakanlah salat dan suruhlah manusia berbuat yang makruf dan cegahlah dari yang mungkar, serta bersabarlah terhadap apa yang menimpamu»."),
"virtues_053": ("Tiga sifat apa yang Al-Qur'an nisbatkan pada orang bertakwa dalam surah Ali 'Imran?", ["Berinfak di waktu lapang dan sempit, menahan amarah, memaafkan orang", "Puasa, salat malam, diam", "Membangun, menanam, memberi", "Bepergian, belajar, mengajar"], "«Yaitu orang yang berinfak, baik di waktu lapang maupun sempit, dan orang yang menahan amarahnya dan memaafkan kesalahan orang: Allah mencintai orang yang berbuat kebaikan»."),
"virtues_054": ("Apa yang Al-Qur'an nilai lebih baik daripada sedekah yang diiringi menyakiti?", ["Perkataan yang baik dan pemberian maaf", "Pemberian yang lebih besar", "Diam sepenuhnya", "Sebuah sumpah"], "«Perkataan yang baik dan pemberian maaf lebih baik daripada sedekah yang diiringi tindakan yang menyakiti»."),
"virtues_055": ("Apa yang Al-Qur'an katakan tentang sedekah yang diberikan secara sembunyi?", ["Itu lebih baik bagi yang memberi", "Itu tidak dihitung", "Itu harus diumumkan", "Itu dilarang"], "«Jika kamu menampakkan sedekahmu, itu baik; tetapi jika kamu menyembunyikannya dan memberikannya kepada orang-orang fakir, itu lebih baik bagimu»."),
"virtues_056": ("Dari apa Al-Qur'an melarang bersedekah?", ["Dari yang buruk, yang kamu sendiri tidak mau mengambilnya kecuali dengan memicingkan mata", "Dari yang baru", "Dari yang dicintai", "Dari warisan"], "«Dan janganlah kamu memilih yang buruk untuk kamu keluarkan, padahal kamu sendiri tidak mau mengambilnya melainkan dengan memicingkan mata»."),
"virtues_057": ("Kapan kebajikan sejati dicapai menurut surah Ali 'Imran?", ["Dengan menginfakkan sebagian dari yang dicintai", "Dengan menginfakkan kelebihan", "Dengan berinfak di depan umum", "Dengan menyimpan semuanya"], "«Kamu tidak akan memperoleh kebajikan sebelum kamu menginfakkan sebagian harta yang kamu cintai»."),
"virtues_058": ("Perumpamaan apa yang Al-Qur'an pakai untuk keseimbangan dalam berinfak?", ["Jangan menjadikan tangan terbelenggu di leher dan jangan pula mengulurkannya sepenuhnya", "Menutup pintu", "Berjalan pelan", "Menghitung dua kali"], "«Dan janganlah engkau jadikan tanganmu terbelenggu pada lehermu dan jangan pula engkau terlalu mengulurkannya, nanti engkau menjadi tercela dan menyesal»."),
"virtues_059": ("Bagaimana Al-Qur'an menggambarkan infak «hamba-hamba Yang Maha Pengasih»?", ["Tidak berlebihan dan tidak kikir, melainkan pertengahan", "Selalu memberi tanpa ukuran", "Selalu berhemat", "Tidak pernah memberi"], "«Dan orang-orang yang apabila menginfakkan harta, mereka tidak berlebihan dan tidak pula kikir, tetapi pertengahan di antara keduanya»."),
"virtues_060": ("Apa yang Al-Qur'an perintahkan sebelum masuk ke rumah yang bukan miliknya?", ["Meminta izin dan memberi salam kepada penghuninya", "Mengetuk tiga kali lalu masuk", "Langsung masuk", "Memanggil dari jauh"], "«Janganlah kamu memasuki rumah yang bukan rumahmu sebelum meminta izin dan memberi salam kepada penghuninya»."),
"virtues_061": ("Apa yang harus dilakukan bila tamu diminta kembali, menurut surah An-Nur?", ["Kembali: itu lebih suci baginya", "Memaksa", "Menunggu di pintu", "Tetap masuk"], "«Dan jika dikatakan kepadamu: “Kembalilah”, maka kembalilah: itu lebih suci bagimu»."),
"virtues_062": ("Apa yang Al-Qur'an perintahkan ketika orang yang tidak dapat dipercaya membawa berita?", ["Memeriksanya, agar tidak menimpakan musibah pada suatu kaum karena kebodohan", "Menyebarkannya segera", "Menuliskannya", "Selalu mengabaikannya"], "«Jika seseorang yang fasik datang kepadamu membawa berita, maka telitilah kebenarannya, agar kamu tidak mencelakakan suatu kaum karena kebodohan, yang akhirnya kamu menyesal»."),
"virtues_063": ("Perilaku apa yang surah Al-Hujurat larang bersama ghibah?", ["Memata-matai dan berprasangka berlebihan", "Bepergian sendiri", "Berbicara pelan", "Menulis surat"], "«Wahai orang-orang yang beriman! Jauhilah banyak prasangka: sesungguhnya sebagian prasangka itu dosa. Dan janganlah kamu mencari-cari kesalahan orang lain dan janganlah menggunjing satu sama lain»."),
"virtues_064": ("Apa yang Al-Qur'an perintahkan bila dua golongan orang beriman berperang?", ["Mendamaikan keduanya dengan adil", "Memihak salah satu", "Mengabaikan mereka", "Memisahkan hanya dengan kekerasan"], "«Dan apabila ada dua golongan orang mukmin berperang, maka damaikanlah antara keduanya… dan berlakulah adil: sungguh Allah mencintai orang-orang yang berlaku adil»."),
"virtues_065": ("Apa yang Al-Qur'an larang dengan tegas, bahkan terhadap kaum yang dibenci?", ["Kebencian yang membuat berlaku tidak adil", "Perdagangan", "Perkataan", "Ketetanggaan"], "«Dan janganlah kebencianmu terhadap suatu kaum mendorong kamu untuk berlaku tidak adil. Berlaku adillah: karena adil itu lebih dekat kepada takwa»."),
"virtues_066": ("Terhadap siapa Al-Qur'an menuntut kesaksian yang adil, bila perlu?", ["Terhadap diri sendiri, ibu bapak, dan kaum kerabat", "Hanya terhadap orang asing", "Hanya terhadap orang kaya", "Hanya terhadap orang miskin"], "«Jadilah kamu penegak keadilan, menjadi saksi karena Allah, walaupun terhadap dirimu sendiri atau terhadap ibu bapak dan kaum kerabatmu»."),
"virtues_067": ("Apa yang Al-Qur'an perintahkan untuk dikembalikan kepada yang berhak?", ["Amanat-amanat", "Surat-surat", "Panen", "Kisah-kisah"], "«Sesungguhnya Allah menyuruhmu menyampaikan amanat kepada yang berhak menerimanya, dan apabila kamu menetapkan hukum di antara manusia hendaknya kamu menetapkannya dengan adil»."),
"virtues_068": ("Siapa saja yang ayat 4:36 sebutkan untuk diperlakukan baik, setelah ibu bapak?", ["Kerabat, anak yatim, orang miskin, tetangga dekat dan jauh, teman sejawat, ibnu sabil, dan hamba sahaya", "Raja dan pemimpin", "Para pedagang", "Hanya para ulama"], "«Dan sembahlah Allah dan janganlah kamu mempersekutukan-Nya dengan sesuatu apa pun. Dan berbuat baiklah kepada kedua orang tua, karib kerabat, anak yatim, orang miskin, tetangga dekat dan tetangga jauh, teman sejawat, ibnu sabil, dan hamba sahaya yang kamu miliki»."),
"virtues_069": ("Apa yang Al-Qur'an perintahkan terhadap orang berutang yang kesulitan?", ["Memberinya tenggang waktu sampai lapang", "Mengejarnya", "Melipatgandakan utangnya", "Mengusirnya"], "«Dan jika dia dalam kesulitan, berilah tenggang waktu sampai dia memperoleh kelapangan; dan menyedekahkan sebagian atau semua utang itu lebih baik bagimu»."),
"virtues_070": ("Apa yang diperintahkan oleh ayat terpanjang Al-Qur'an mengenai utang berjangka?", ["Menuliskannya", "Merahasiakannya", "Melupakannya", "Menyampaikannya secara lisan"], "«Wahai orang-orang yang beriman! Apabila kamu melakukan utang piutang untuk waktu yang ditentukan, hendaklah kamu menuliskannya»."),
"virtues_071": ("Apa yang Al-Qur'an larang berkenaan dengan harta orang lain?", ["Memakannya dengan cara batil, atau memakainya untuk menyuap hakim", "Menghitungnya", "Menjualnya", "Menjaganya"], "«Dan janganlah kamu makan harta di antara kamu dengan jalan yang batil, dan janganlah kamu menyuap dengan harta itu kepada para hakim untuk memakan sebagian harta orang lain dengan jalan dosa»."),
"virtues_072": ("Apa yang Al-Qur'an perintahkan mengenai harta anak yatim?", ["Menyerahkannya kepada mereka, tanpa menukar yang baik dengan yang buruk", "Membaginya", "Menjualnya", "Menahannya seumur hidup"], "«Dan berikanlah kepada anak-anak yatim harta mereka; janganlah kamu menukar yang baik dengan yang buruk dan janganlah kamu makan harta mereka bersama hartamu»."),
"virtues_073": ("Bagaimana Al-Qur'an memerintahkan menakar dan menimbang?", ["Menyempurnakan takaran dan menimbang dengan neraca yang benar", "Membulatkan demi keuntungan sendiri", "Menimbang dengan perkiraan", "Menakar dua kali"], "«Dan sempurnakanlah takaran apabila kamu menakar, dan timbanglah dengan neraca yang benar: itulah yang lebih utama dan lebih baik akibatnya»."),
"virtues_074": ("Apa yang Al-Qur'an larang diikuti tanpa ilmu?", ["Apa yang tidak diketahui: pendengaran, penglihatan, dan hati akan dimintai pertanggungjawaban", "Jalan terpendek", "Kafilah", "Diam"], "«Dan janganlah kamu mengikuti sesuatu yang tidak kamu ketahui: sesungguhnya pendengaran, penglihatan, dan hati nurani, semua itu akan diminta pertanggungjawabannya»."),
"virtues_075": ("Perumpamaan apa yang Al-Qur'an berikan tentang kesombongan dalam berjalan?", ["Kamu tidak akan mampu menembus bumi maupun menyamai tinggi gunung", "Kamu berjalan lebih cepat", "Kamu tidak mudah lelah", "Kamu dihormati"], "«Dan janganlah engkau berjalan di bumi ini dengan sombong: sungguh, engkau tidak akan dapat menembus bumi dan tidak akan mampu menjulang setinggi gunung»."),
"virtues_076": ("Sifat perkataan apa yang Al-Qur'an perintahkan, dengan janji amal akan diperbaiki?", ["Perkataan yang benar dan tepat (qaulan sadidan)", "Perkataan yang singkat", "Perkataan yang berilmu", "Perkataan yang tertulis"], "«Wahai orang-orang yang beriman! Bertakwalah kamu kepada Allah dan ucapkanlah perkataan yang benar: niscaya Dia akan memperbaiki amal-amalmu dan mengampuni dosa-dosamu»."),
"virtues_077": ("Perkataan macam apa yang diperintahkan bahkan di hadapan seorang tiran, dalam Al-Qur'an?", ["Perkataan yang lemah lembut", "Perkataan yang mengancam", "Perkataan yang menyindir", "Diam"], "«Berbicaralah kamu berdua kepadanya dengan kata-kata yang lemah lembut: mudah-mudahan dia sadar atau takut»."),
"virtues_078": ("Tentang siapa Al-Qur'an mengatakan perkataannya paling baik?", ["Orang yang menyeru kepada Allah, beramal saleh, dan berkata: aku termasuk orang muslim", "Penyair", "Ahli pidato", "Hakim"], "«Dan siapakah yang lebih baik perkataannya daripada orang yang menyeru kepada Allah dan mengerjakan kebajikan dan berkata: sungguh, aku termasuk orang-orang muslim?»"),
"virtues_079": ("Dari apa orang beriman yang beruntung berpaling menurut Al-Mu'minun?", ["Dari perbuatan dan perkataan sia-sia (al-laghw)", "Dari pekerjaan", "Dari perjalanan", "Dari makanan"], "«…dan orang yang menjauhkan diri dari perbuatan dan perkataan yang tidak berguna»."),
"virtues_080": ("Dua tanggungan apa yang dijaga orang beriman yang beruntung menurut Al-Mu'minun?", ["Amanat yang dipercayakan kepada mereka dan janji mereka", "Puasa dan salat malam", "Perjalanan dan perdagangan", "Menulis dan membaca"], "«Dan orang yang memelihara amanat-amanat dan janjinya»."),
"virtues_081": ("Apa yang Al-Qur'an katakan tentang orang yang memaafkan dan berdamai, padahal mampu membalas?", ["Pahalanya menjadi tanggungan Allah", "Dia kehilangan haknya", "Dia tercela", "Dia harus diam"], "«Dan balasan suatu kejahatan adalah kejahatan yang setimpal; tetapi barang siapa memaafkan dan berbuat baik, maka pahalanya dari Allah»."),
"virtues_082": ("Alasan apa yang Al-Qur'an berikan untuk memaafkan orang yang menzalimi kita?", ["«Tidakkah kamu suka bahwa Allah mengampunimu?»", "«Kamu akan diberi ganti uang»", "«Itu membuatmu berkuasa»", "«Itu menghindarkanmu dari perkara»"], "«Dan hendaklah mereka memaafkan dan berlapang dada. Apakah kamu tidak suka bahwa Allah mengampunimu? Dan Allah Maha Pengampun, Maha Penyayang»."),
"virtues_083": ("Tiga perintah apa yang dihimpun ayat 7:199?", ["Memaafkan, menyuruh berbuat makruf, dan berpaling dari orang bodoh", "Berperang, lari, diam", "Makan, minum, tidur", "Menghitung, menulis, membaca"], "«Jadilah pemaaf, dan suruhlah orang mengerjakan yang makruf, serta berpalinglah dari orang-orang bodoh»."),
"virtues_084": ("Sikap apa yang Al-Qur'an anjurkan menghadapi kata-kata menyakitkan dan ujian?", ["Sabar dan takwa: itu termasuk urusan yang patut diutamakan", "Membalas segera", "Menarik diri selamanya", "Diam yang meremehkan"], "«Dan kamu pasti akan mendengar banyak hal yang menyakitkan hati dari orang-orang yang diberi Kitab sebelum kamu. Jika kamu bersabar dan bertakwa, maka sesungguhnya yang demikian itu termasuk urusan yang patut diutamakan»."),
"virtues_085": ("Bagaimana Al-Qur'an menyifati kesabaran dan pemaafan?", ["Termasuk urusan yang patut diutamakan", "Sebuah kelemahan", "Bersifat pilihan", "Hanya untuk ulama"], "«Tetapi barang siapa bersabar dan memaafkan, sungguh yang demikian itu termasuk perbuatan yang mulia»."),
"virtues_086": ("Bagi siapa salat itu tidak terasa berat menurut Al-Qur'an?", ["Bagi orang-orang yang khusyuk kepada Allah", "Bagi orang kaya", "Bagi para ulama", "Bagi musafir"], "«Dan mohonlah pertolongan dengan sabar dan salat: sungguh yang demikian itu berat, kecuali bagi orang-orang yang khusyuk»."),
"virtues_087": ("Apa yang Al-Qur'an ingatkan tentang apa yang dibenci atau disukai?", ["Boleh jadi kamu membenci sesuatu padahal itu baik bagimu, dan menyukai sesuatu padahal itu buruk", "Yang kamu sukai selalu baik", "Yang kamu benci selalu buruk", "Manusia selalu tahu yang baik"], "«Boleh jadi kamu membenci sesuatu padahal itu baik bagimu, dan boleh jadi kamu menyukai sesuatu padahal itu buruk bagimu. Allah mengetahui sedang kamu tidak mengetahui»."),
"virtues_088": ("Apa yang Al-Qur'an janjikan bagi orang yang bertakwa, dalam hal jalan keluar dan rezeki?", ["Jalan keluar dan rezeki dari arah yang tidak disangka", "Kekayaan seketika", "Perjalanan panjang", "Sebuah jabatan"], "«Barang siapa bertakwa kepada Allah, niscaya Dia akan membukakan jalan keluar baginya, dan memberinya rezeki dari arah yang tidak disangka-sangka»."),
"virtues_089": ("Syukur apa yang Al-Qur'an perintahkan bersamaan dengan syukur kepada Allah?", ["Syukur kepada kedua orang tua", "Kepada majikan", "Kepada tetangga", "Kepada raja"], "«Bersyukurlah kepada-Ku dan kepada kedua orang tuamu: hanya kepada-Ku kembalimu»."),
"virtues_090": ("Batas apa yang Al-Qur'an tetapkan bagi ketaatan kepada orang tua?", ["Tidak menaati mereka bila menyuruh mempersekutukan Allah", "Tidak pernah menaati mereka", "Menaati mereka dalam segala hal", "Menaati mereka hanya dalam perjalanan"], "«Dan jika keduanya memaksamu untuk mempersekutukan Aku dengan sesuatu yang engkau tidak mempunyai ilmu tentang itu, maka janganlah engkau menaati keduanya; dan pergaulilah keduanya di dunia dengan baik»."),
"virtues_091": ("Doa apa yang Al-Qur'an ajarkan tentang orang tua dan keturunan?", ["Mensyukuri nikmat, beramal saleh, dan agar keturunan diperbaiki", "Meminta kekayaan", "Meminta perjalanan panjang", "Meminta jabatan"], "«Ya Tuhanku, berilah aku petunjuk agar aku dapat mensyukuri nikmat-Mu yang telah Engkau limpahkan kepadaku dan kepada kedua orang tuaku dan agar aku dapat berbuat kebajikan yang Engkau ridai; dan berilah aku kebaikan pada keturunanku»."),
"virtues_092": ("Apa yang «hamba-hamba Yang Maha Pengasih» minta tentang keluarga mereka?", ["Agar menjadi penyenang hati, dan agar mereka menjadi teladan bagi orang bertakwa", "Agar kaya", "Agar banyak", "Agar bepergian"], "«Ya Tuhan kami, anugerahkanlah kepada kami pasangan dan keturunan kami sebagai penyenang hati, dan jadikanlah kami pemimpin bagi orang-orang yang bertakwa»."),
"virtues_093": ("Bagaimana «hamba-hamba Yang Maha Pengasih» bersikap terhadap perkara sia-sia?", ["Mereka melaluinya dengan menjaga kehormatan diri", "Mereka berhenti untuk mendengarkan", "Mereka membalas dengan keras", "Mereka menuliskannya"], "«Dan orang-orang yang tidak memberikan kesaksian palsu, dan apabila mereka bertemu dengan orang-orang yang mengerjakan perbuatan sia-sia, mereka berlalu dengan menjaga kehormatan dirinya»."),
"virtues_094": ("Apa yang Al-Qur'an perintahkan dalam suatu majelis ketika diminta memberi tempat?", ["Memberi kelapangan: Allah akan memberi kelapangan untukmu", "Tetap berdesakan", "Keluar", "Diam"], "«Wahai orang-orang yang beriman! Apabila dikatakan kepadamu: “Berilah kelapangan di dalam majelis”, maka lapangkanlah: niscaya Allah akan memberi kelapangan untukmu»."),
"virtues_095": ("Bersama siapa Al-Qur'an memerintahkan agar berada, dalam surah At-Taubah?", ["Bersama orang-orang yang benar", "Bersama orang-orang berkuasa", "Bersama orang-orang kaya", "Bersama para musafir"], "«Wahai orang-orang yang beriman! Bertakwalah kepada Allah dan bersamalah kamu dengan orang-orang yang benar»."),
"virtues_096": ("Bersama siapa Al-Qur'an memerintahkan Nabi ﷺ bersabar, dalam Al-Kahfi?", ["Bersama orang-orang yang menyeru Tuhannya pagi dan petang mengharap keridaan-Nya", "Bersama para kepala suku", "Bersama pedagang kaya", "Bersama para penyair"], "«Dan bersabarlah engkau bersama orang-orang yang menyeru Tuhannya pada pagi dan senja hari dengan mengharap keridaan-Nya; dan janganlah kedua matamu berpaling dari mereka»."),
"virtues_097": ("Dalam hal apa Al-Qur'an memerintahkan tolong-menolong, dan dalam hal apa melarangnya?", ["Tolong-menolong dalam kebajikan dan takwa, bukan dalam dosa dan permusuhan", "Tolong-menolong dalam segala hal", "Tidak menolong siapa pun", "Menolong hanya keluarga"], "«Dan tolong-menolonglah kamu dalam kebajikan dan takwa, dan jangan tolong-menolong dalam berbuat dosa dan permusuhan»."),
"virtues_098": ("Apa yang Al-Qur'an perintahkan tentang perjanjian yang dibuat dan sumpah yang dikukuhkan?", ["Memenuhi janji dan tidak membatalkan sumpah setelah dikukuhkan", "Merundingkannya kembali", "Melupakannya", "Menyembunyikannya"], "«Dan tepatilah janji dengan Allah apabila kamu berjanji, dan janganlah kamu melanggar sumpah setelah diikrarkan»."),
"virtues_099": ("Menurut hadis riwayat al-Bukhari, kapan iman seseorang menjadi sempurna?", ["Ketika dia mencintai untuk saudaranya apa yang dia cintai untuk dirinya", "Ketika dia berpuasa sepanjang tahun", "Ketika dia memberikan seluruh hartanya", "Ketika dia pergi ke Makkah"], "«Tidak beriman salah seorang di antara kamu sehingga dia mencintai untuk saudaranya apa yang dia cintai untuk dirinya sendiri»."),
"virtues_100": ("Dalam hal apa Al-Qur'an melihat kebaikan dalam pembicaraan rahasia?", ["Menyuruh bersedekah, berbuat kebaikan, atau mendamaikan manusia", "Membicarakan bisnis", "Merencanakan perjalanan", "Menyampaikan kabar"], "«Tidak ada kebaikan dalam banyak pembicaraan rahasia mereka, kecuali pembicaraan orang yang menyuruh bersedekah, atau berbuat kebaikan, atau mendamaikan di antara manusia»."),
}
